const now = new Date();
const VENTANA_24H = 24 * 60 * 60 * 1000;
const VENTANA_4H = 4 * 60 * 60 * 1000;
// MARGEN 30 min (antes 15): la ventana (60 min) supera al intervalo del scanner (30 min),
// asi cada evento cae en DOS pasadas y un envio fallido tiene una segunda oportunidad.
const MARGEN = 30 * 60 * 1000;
const LIMPIEZA_48H = 48 * 60 * 60 * 1000;

// Ventana horaria de emision (hora de Madrid). Sin esto, el aviso de 4h de una cita de
// primera hora sale de madrugada: 4h antes de las 10:30 son las 06:30.
const HORA_MIN = 9 * 60;        // 09:00
const HORA_MAX = 21 * 60 + 30;  // 21:30
const hm = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit', hour12: false
}).format(now).split(':');
const minutosAhora = Number(hm[0]) * 60 + Number(hm[1]);
const dentroDeHorario = minutosAhora >= HORA_MIN && minutosAhora <= HORA_MAX;

const staticData = $getWorkflowStaticData('global');
staticData.enviados = staticData.enviados || {};

for (const clave of Object.keys(staticData.enviados)) {
  if (now.getTime() - staticData.enviados[clave] > LIMPIEZA_48H) {
    delete staticData.enviados[clave];
  }
}

const resultados = [];

for (const item of $input.all()) {
  const evento = item.json;
  const fechaEvento = new Date(evento.start.dateTime || evento.start.date);
  const diff = fechaEvento - now;

  if (diff < 0) continue;

  const es24h = diff > (VENTANA_24H - MARGEN) && diff < (VENTANA_24H + MARGEN);
  const es4h = diff > (VENTANA_4H - MARGEN) && diff < (VENTANA_4H + MARGEN);

  if (!es24h && !es4h) continue;

  // Fuera de horario no se escribe al paciente. El de 24h ya le avisó; reenviarlo
  // mas tarde perderia el sentido del "faltan 4 horas".
  if (!dentroDeHorario) continue;

  const tipo = es24h ? '24h' : '4h';
  const clave = `${evento.id}_${tipo}`;

  if (staticData.enviados[clave]) continue;

  const descripcion = evento.description || '';
  const leadMatch = descripcion.match(/Lead\s*ID:\s*(\d+)/i);
  if (!leadMatch) continue;

  const leadId = leadMatch[1];

  const telMatch = descripcion.match(/\+?34\s*\d[\d\s]{7,}\d/);
  const telefono = telMatch ? telMatch[0].replace(/\s+/g, '') : null;

  let nombreCliente = 'Cliente';
  const nombreMatch = (evento.summary || '').match(/-\s*([^-]+)$/);
  if (nombreMatch) nombreCliente = nombreMatch[1].trim();

  // NO se marca aqui: la marca la ponen los nodos "Marcar enviado" DESPUES del envio OK.
  resultados.push({
    leadId,
    telefono,
    nombreCliente,
    tipoRecordatorio: tipo,
    eventoId: evento.id
  });
}

return resultados.map((json) => ({ json }));

// Se ejecuta despues del envio. Solo marca lo que Kommo acepto: si el HTTP fallo
// (onError: continueRegularOutput), el item trae `error` y la clave NO se escribe,
// asi la siguiente pasada del scanner reintenta.
const sd = $getWorkflowStaticData('global');
sd.enviados = sd.enviados || {};

if (!$json.error) {
  const src = $('Filtrar y evitar duplicados').item.json;
  sd.enviados[`${src.eventoId}_${src.tipoRecordatorio}`] = Date.now();
}

return $input.item;

